<?php
/** Authored reading aids; the renderer never derives or revises a scientific conclusion. */
function wf_usefulness_schema(): array {
 $out=['version'=>['const'=>1]];foreach(['question_helped','intended_user','finding','why_it_matters','increment','established','uncertain','reusable_output','next_use'] as $key)$out[$key]=['type'=>'string','minBytes'=>10,'maxBytes'=>2000];return ['type'=>'object','properties'=>$out,'required'=>array_keys($out)];
}
function wf_usefulness_validate(array $packet): array {
 $value=$packet['usefulness']??null;if(!is_array($value))fail(422,'Describe the useful increment and readable finding in usefulness version 1. A null result or clarified uncertainty is eligible; no breakthrough or invented impact metric is required.');
 $errors=[];wf_schema_walk($value,wf_usefulness_schema(),'$.usefulness',$errors);if($errors)wf_packet_throw($errors);$out=['version'=>1];foreach(array_keys(wf_usefulness_schema()['properties']) as $key)if($key!=='version')$out[$key]=text_field($value,$key,10,2000);return $out;
}
function wf_usefulness_instructions(): string {return 'MANDATORY READABLE, USEFUL OUTPUT — version 1: Author usefulness with version=1 and question_helped, intended_user, finding, why_it_matters, increment, established, uncertain, reusable_output, next_use (10–2000 UTF-8 bytes each). Copy usefulness.finding verbatim into the full body so the reading aid cannot introduce a detached scientific claim. Start with a plain-English finding, then why it matters, useful work added, what is and is not established, reusable output and next use. Explain specialist terms before methods/evidence; place inventory/audit after the finding. Assess the actual increment against this task deliverable: evidence organization, synthesis, replication, reproducible checks or clarified uncertainty can be useful. A careful null or unresolved result is eligible; listing sources, valid JSON, Check, a receipt or workflow completion alone is insufficient. Do not invent impact/saved-hour metrics or compute just to populate a schema. Preserve units, denominators, conditions, uncertainty and evidence-appropriate precision. Do not reinterpret signed aggregate velocity as slower sinking when aggregates can rise; distinguish aggregate from fibre motion. Strictly formatting-only changes are mandatory for readability and must preserve every scientific claim, method, evidence choice, conclusion and uncertainty. Scientific/editorial guidance beyond formatting must be disclosed truthfully. Historical results/disclosures are never rewritten by this policy.';}
function wf_formatting_influence(array $influence,?array $trustedConsent=null): array {
 // A packet cannot select this policy. Only future server-captured consent enables it.
 $version=$trustedConsent['influence_policy_version']??null;$out=$influence;
 foreach(['human_interaction','human_disclosure'] as $key){$category=$out[$key]['category']??'';if(!in_array($category,['','none','setup_access','platform_repair','formatting','editorial','methodology','evidence','conclusion','uncertain'],true))fail(422,'Unknown human-input category; report the actual input without concealing scientific influence.');}
 foreach(['human_interaction','human_disclosure'] as $key){$value=$out[$key]??[];if(($value['level']??'')!=='formatting_only')continue;if($version!=='formatting-only-v1')fail(422,'Formatting-only disclosure requires newly captured authorization for the current formatting policy. Preserve the historical disclosure.');if(($value['category']??'')!=='formatting')fail(422,'Formatting-only input must preserve science and declare category formatting. Method, evidence, conclusion or uncertain input requires influence review.');}
 $held=false;foreach(['human_interaction','human_disclosure'] as $key){$v=$out[$key]??[];if(in_array($v['level']??'', ['influenced','unsure'],true)||in_array($v['category']??'', ['editorial','methodology','evidence','conclusion','uncertain'],true))$held=true;}
 if($version==='formatting-only-v1'){$out['policy_version']=$version;$out['review_status']=$held?'needed':'not_requested';}
 return $out;
}

function wf_usefulness_review_template(array $task): array {
 $out=[];if(!in_array($task['kind'],['review','contribution_review'],true))return $out;foreach(wf_evidence_results($task) as $target)$out[]=['task_id'=>$target['task']['id'],'result_id'=>$target['result']['id'],'verdict'=>'','reason'=>'','output_quote'=>'','next_use'=>''];return $out;
}
function wf_usefulness_reviews(array $task,array $data,array $row): array {
 $reviews=$data['usefulness_reviews']??[];if(!is_array($reviews)||!array_is_list($reviews)||count($reviews)>40)fail(422,'Usefulness reviews must be a list of at most 40 current result assessments.');
 $targets=[];foreach(wf_usefulness_review_template($task) as $target)$targets[$target['task_id'].'/'.$target['result_id']]=$target;$current=wf_evidence_results($task);$seen=[];$clean=[];$corrections=[];
 foreach($reviews as $review){if(!is_array($review))fail(422,'Each usefulness review must be an object.');$tid=text_field($review,'task_id',32,32);$rid=text_field($review,'result_id',32,32);$key=$tid.'/'.$rid;if(!isset($targets[$key])||isset($seen[$key]))fail(422,'Usefulness review must identify each current accepted target once.');$seen[$key]=true;$verdict=wf_evidence_choice($review,'verdict',['useful','needs_correction','unverifiable']);$reason=text_field($review,'reason',20,3000);$quote=text_field($review,'output_quote',1,2000);$next=text_field($review,'next_use',10,2000);$result=$current[$rid]['result'];$readable=json_decode($result['metadata'],true)['usefulness']??[];$retained=implode("\n",array_map(fn($f)=>(string)($result[$f]??''),['body','methodology','sources','limitations']))."\n".implode("\n",array_filter($readable,'is_string'));if(!str_contains($retained,$quote))fail(422,'Usefulness output_quote must match the retained result exactly; never invent an output or saved effort.');
 if($verdict!=='useful'){if($row['outcome']!=='needs_correction')fail(422,'Missing or unverifiable useful work requires needs_correction; a schema or receipt is not sufficient.');$corrections[]=['task_id'=>$tid,'result_id'=>$rid,'criterion_id'=>'usefulness-standard','reason'=>substr($reason,0,1000),'required_change'=>'Reassess the actual useful increment against the requested deliverable: '.substr($reason,0,2000).' Preserve null findings and scientific uncertainty; do not invent impact metrics or force a positive conclusion.'];}
 $clean[]=['task_id'=>$tid,'result_id'=>$rid,'verdict'=>$verdict,'reason'=>$reason,'output_quote'=>$quote,'next_use'=>$next];
 }
 if($row['outcome']==='verified'&&count($seen)!==count($targets))fail(422,'Verified review must assess actual useful work for every current accepted result, including historical results without an authored reading aid.');return ['fields'=>['usefulness_reviews'=>$clean],'corrections'=>$corrections];
}
